record.field:
# Available variables: # - env: environment on which the action is triggered # - model: model of the record on which the action is triggered; is a void recordset # - record: record on which the action is triggered; may be void # - records: recordset of all records on which the action is triggered in multi-mode; may be void # - time, datetime, dateutil, timezone: useful Python libraries # - float_compare: utility function to compare floats based on specific precision # - log: log(message, level='info'): logging function to record debug information in ir.logging table # - _logger: _logger.info(message): logger to emit messages in server logs # - UserError: exception class for raising user-facing warning messages # - Command: x2many commands namespace # To return an action, assign: action = {...} # Obtener el registro record = records[0]
action = None
# Partner que respondió partner = record.partner_id
# Almacén asignado al partner warehouse = partner.x_studio_warehouse_id
if not warehouse: action = { "type": "ir.actions.client", "tag": "display_notification", "params": { "title": "Sin almacén", "message": "Este contacto no tiene almacén asignado.", "type": "warning", }, }
else: # Ubicación del almacén location = warehouse.lot_stock_id
# ---------------------------- # Productos elegidos en encuesta # ---------------------------- products = env["product.product"]
for line in record.user_input_line_ids:
if "suggested_answer_ids" in line._fields: answers = line.suggested_answer_ids else: answers = line.suggested_answer_id or env["survey.question.answer"]
products |= answers.mapped("x_studio_product_product_id")
if not products: action = { "type": "ir.actions.client", "tag": "display_notification", "params": { "title": "Sin producto", "message": "No hay productos vinculados a las respuestas.", "type": "warning", }, }
else: # ---------------------------- # Solo últimos 15 días # ---------------------------- date_limit = datetime.datetime.now() - dateutil.relativedelta.relativedelta(days=15)
# Transferencias / recepciones hacia esa ubicación con esos productos action = { "type": "ir.actions.act_window", "name": "Transferencias relacionadas", "res_model": "stock.picking", "view_mode": "tree,form", "domain": [ ("move_ids_without_package.product_id", "in", products.ids), ("location_dest_id", "child_of", location.id), ("state", "not in", ["cancel", "done"]), ("scheduled_date", ">=", date_limit), ], }

# Available variables: # - env: environment on which the action is triggered # - model: model of the record on which the action is triggered; is a void recordset # - record: record on which the action is triggered; may be void # - records: recordset of all records on which the action is triggered in multi-mode; may be void # - time, datetime, dateutil, timezone: useful Python libraries # - float_compare: utility function to compare floats based on specific precision # - log: log(message, level='info'): logging function to record debug information in ir.logging table # - _logger: _logger.info(message): logger to emit messages in server logs # - UserError: exception class for raising user-facing warning messages # - Command: x2many commands namespace # To return an action, assign: action = {...}
# Obtener el registro record = records[0]
action = None
# Partner que respondió partner = record.partner_id
# Almacén asignado al partner warehouse = partner.x_studio_warehouse_id
if not warehouse: action = { "type": "ir.actions.client", "tag": "display_notification", "params": { "title": "Sin almacén", "message": "Este contacto no tiene almacén asignado.", "type": "warning", }, }
else: # Ubicación del almacén location = warehouse.lot_stock_id
# ---------------------------- # Productos elegidos en encuesta # ---------------------------- products = env["product.product"]
for line in record.user_input_line_ids:
# Si existe el campo de respuestas múltiples if "suggested_answer_ids" in line._fields: answers = line.suggested_answer_ids else: # Si es respuesta simple (una línea por opción) answers = line.suggested_answer_id or env["survey.question.answer"]
products |= answers.mapped("x_studio_product_product_id")
# Sin productos vinculados if not products: action = { "type": "ir.actions.client", "tag": "display_notification", "params": { "title": "Sin producto", "message": "No hay productos vinculados a las respuestas.", "type": "warning", }, } else: # Abrir quants filtrados action = { "type": "ir.actions.act_window", "name": "Stock del punto de venta", "res_model": "stock.quant", "view_mode": "tree,form", "domain": [ ("product_id", "in", products.ids), ("location_id", "child_of", location.id), ], }
